88: static ra_filter_t *ra_filter_init(ra_filter_t *filter, size_t sample_size) {
89:   memset(filter, 0, sizeof(ra_filter_t));
90: 
91:   filter->values = (int *)malloc(sample_size * sizeof(int));
92:   if (!filter->values) {
93:     return NULL;
