101: #if ARDUHAL_LOG_LEVEL >= ARDUHAL_LOG_LEVEL_INFO
102: static int ra_filter_run(ra_filter_t *filter, int value) {
103:   if (!filter->values) {
104:     return value;
105:   }
106:   filter->sum -= filter->values[filter->index];
107:   filter->values[filter->index] = value;
108:   filter->sum += filter->values[filter->index];
109:   filter->index++;
110:   filter->index = filter->index % filter->size;
111:   if (filter->count < filter->size) {
112:     filter->count++;
113:   }
114:   return filter->sum / filter->count;
115: }
