470: 
471:     for (int reg = 0x5580; reg < 0x558a; reg++) {
472:       p += print_reg(p, s, reg, 0xFF);
473:     }
474:     p += print_reg(p, s, 0x558a, 0x1FF);  //9 bit
475:   } else if (s->id.PID == OV2640_PID) {
476:     p += print_reg(p, s, 0xd3, 0xFF);
477:     p += print_reg(p, s, 0x111, 0xFF);
478:     p += print_reg(p, s, 0x132, 0xFF);
479:   }
480: 
