@cam_app.get("/video_feed")
def video_feed():
    def gen():
        last = None
        while True:
            with out_lock:
                jpeg = output["jpeg"]
            if jpeg is None:
                jpeg = PLACEHOLDER
            if jpeg is not last:
                yield (
                    b"--frame\r\n"
                    b"Content-Type: image/jpeg\r\n\r\n" + jpeg + b"\r\n"
                )
                last = jpeg
            time.sleep(0.05)  # 20fps đủ cho mắt người; 0.03 cũ tốn CPU mà vẫn chỉ có ~6-10 khung mới/s

    resp = Response(
        gen(), mimetype="multipart/x-mixed-replace; boundary=frame"
    )
    # Chặn proxy/buffer trung gian dồn khung gây lag cảm nhận.
    resp.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
    resp.headers["Pragma"] = "no-cache"
    resp.headers["X-Accel-Buffering"] = "no"
    return resp

