    if (!cls) { toast('Chọn lớp', true); return; }
    if (!files.length) { toast('Chọn ảnh khuôn mặt (tải lên)', true); return; }
    if (files.length > 8) { toast('Tối đa 8 ảnh mỗi lần', true); return; }
    $('regMsg').textContent = 'Đang đăng ký…';
    readFiles(files).then(function (images) {
      return api('/api/students', {method:'POST', headers:{'Content-Type':'application/json'},
        body: JSON.stringify({full_name:name, date_of_birth:dob, class_name:cls, images:images})});
    }).then(function (d) {
      toast('Đã đăng ký ' + name + ' — ' + d.samples + ' mẫu', false);
      setTimeout(function(){ location.reload(); }, 700);
    }).catch(function (err) { $('regMsg').textContent = 'Không đăng ký được: ' + err.message; });
  });
}
function readFiles(files) {
  return Promise.all(Array.prototype.map.call(files, function (f) {
    return new Promise(function (res, rej) {
      var r = new FileReader();
      r.onload = function () { res(r.result); };
      r.onerror = rej;
      r.readAsDataURL(f);
    });
  }));
}
