539:     lastEngine = en;
540:     $('camDot').className = 'dot' + (cam.connected ? ' on' : '');
541:     $('camState').textContent = cam.connected
542:       ? 'đang chạy (' + (cam.fps || '?') + ' fps' + (cam.resolution ? ', ' + cam.resolution : '') + ')'
543:       : (cam.url ? 'mất kết nối' : 'chưa bật');
544:     $('camErr').textContent = cam.error ? ('Lưu ý: ' + cam.error) : '';
545:     if (cam.url && !$('streamUrl').value) $('streamUrl').value = cam.url;
546:     var src = {phone: 'Điện thoại', esp32: 'ESP32', test: 'Test'}[d.frame_source] || 'không có';
547:     $('srcState').textContent = src;
548:     /* ESP32 PUSH đang chạy thì báo thêm để biết không cần nhập URL. */
549:     var esp = d.esp32 || {};
550:     var hint = $('esp32Hint');
551:     if (hint) {
552:       if (esp.push_alive) {
553:         hint.textContent = 'ESP32 đang PUSH (' + esp.push_count + ' khung đã gửi) — nguồn ưu tiên, PULL tạm nhường.';
554:       } else if (d.frame_source === 'esp32') {
555:         hint.textContent = 'ESP32 đang PULL qua ' + (cam.url || 'STREAM_URL') + '.';
556:       } else {
557:         hint.textContent = '';
558:       }
559:     }
560:     $('modelState').textContent =
561:       (ENGINE_NAME[en.detector] || en.detector || '?') + ' + ' +
562:       (ENGINE_NAME[en.recognizer] || en.recognizer || '?') +
563:       (d.students ? ' · ' + d.students + ' người' : '');
564:     $('stuCount').textContent = d.students;
565:     $('faceCount').textContent = d.faces == null ? 0 : d.faces;
566:     $('matchCount').textContent = d.matched == null ? 0 : d.matched;
567:     var t = en.timing_ms || {};
568:     $('speedState').textContent = t.total_ms
569:       ? Math.round(t.total_ms) + ' ms/khung' +
570:         (en.tracking ? ' · ' + en.tracks + ' vùng theo dõi' : '')
571:       : '—';
572:     var live = $('liveBadge');
573:     var off = (d.frame_source === 'none');
574:     live.textContent = off ? 'chờ tín hiệu' : ('đang xử lý (' + d.frame_age + 's)');
575:     live.classList.toggle('off', off);
576:     live.parentNode.classList.toggle('no-signal', off);
577: 
578:     var box = $('dets');
579:     var html;
580:     if (!d.results.length) {
581:       html = '<span class="muted">' +
582:         (d.frame_source !== 'none' ? 'Không thấy khuôn mặt trong khung.' :
583:          'Chưa có khung hình nào được xử lý.') + '</span>';
584:     } else {
585:       html = d.results.map(function (r) {
586:         var tag = r.track_id != null ? '<span class="tag">#' + r.track_id + '</span>' : '';
587:         var dist = '<small>(' + distLabel() + ' ' + esc(r.confidence) + ')</small>';
588:         if (r.match)
589:           return '<span class="det">' + tag + '<b>' + esc(r.full_name) + '</b> · ' +
590:             esc(r.class_name) + ' · ' + esc(r.date_of_birth) + ' ' + dist + '</span>';
591:         if (r.confirming)
592:           return '<span class="det wait">' + tag + 'Đang xác nhận…' +
593:             ' <small>(' + esc(r.full_name || '—') + ') ' + dist + '</small></span>';
594:         return '<span class="det warn">' + tag + 'Chưa nhận diện ' + dist + '</span>';
595:       }).join('');
596:     }
597:     setHTML(box, html);
598: 
599:     /* Khung chuyển từ rỗng sang có mặt -> cụm kết quả bật lên một lần.
