<script>
var $ = function (id) { return document.getElementById(id); };

function toast(msg, isErr){
  var t = $('toast');
  t.textContent = msg;
  t.className = 'toast show' + (isErr ? ' err' : ' ok');
  clearTimeout(t._h);
  t._h = setTimeout(function () { t.className = 'toast'; }, 3200);
}

function api(url, opt){
  return fetch(url, opt).then(function (r) {
    return r.json().catch(function () { return null; }).then(function (data) {
      if (!r.ok || (data && data.ok === false))
        throw new Error((data && data.error) || ('Lỗi ' + r.status));
      return data;
    });
  });
}

/* Chỉ ghi lại khi nội dung THẬT SỰ đổi: bảng poll mỗi 1,5s mà y hệt
   thì không việc gì phải dựng lại DOM (và animation sẽ không nhấp nháy). */
function setHTML(el, html) {
  if (el.innerHTML !== html) el.innerHTML = html;
}

function esc(s) {
  return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
    return {'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c];
  });
}

/* ---------------- khung hình ---------------- */
function grabFrame(){
  return fetch("/api/frame.jpg", {cache: "no-store"}).then(function (r) {
    if (!r.ok) throw new Error("Chưa có khung hình từ camera — chờ camera chạy rồi thử lại");
    return r.blob();
  }).then(function (blob) {
    if (!blob.size) throw new Error("Khung hình rỗng");
    return new Promise(function (resolve, reject) {
      var rd = new FileReader();
      rd.onload = function () { resolve(rd.result); };
      rd.onerror = function () { reject(new Error("Không đọc được khung hình")); };
      rd.readAsDataURL(blob);
    });
  });
}

/* ---------------- cấu hình camera PULL ---------------- */
function connect(restart){
  var url = $('streamUrl').value.trim();
  api('/api/config', {
    method: 'POST', headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({stream_url: url, restart: restart})
  }).then(function () {
    toast(restart ? 'Đang kết nối lại...' : 'Đã lưu cấu hình, đang kết nối...', false);
  }).catch(function (e) { toast(e.message, true); });
}
$('btnConnect').addEventListener('click', function () { connect(false); });
$('btnReconnect').addEventListener('click', function () { connect(true); });

Array.prototype.forEach.call(document.querySelectorAll('[data-preset]'), function (b) {
  b.addEventListener('click', function () {
    var kind = b.getAttribute('data-preset');
    var cur = $('streamUrl').value.trim();
    var ip = (cur.match(/(\d+\.\d+\.\d+\.\d+)/) || [])[1] || '192.168.1.10';
    if (kind === 'esp32') $('streamUrl').value = 'http://' + ip + ':81/stream';
    if (kind === 'droid') $('streamUrl').value = 'http://' + ip + ':4747/video';
    if (kind === 'ipwebcam') $('streamUrl').value = 'http://' + ip + ':8080/video';
    connect(true);
  });
});

/* ---------------- cài đặt ESP32-CAM (qua proxy server) ---------------- */
var espFlip = {vflip: 0, hmirror: 0};
function espCtl(v, val, silent){
  return api('/api/esp32/control?var=' + encodeURIComponent(v) +
             '&val=' + encodeURIComponent(val)).then(function () {
    if (!silent) toast('Đã đặt ' + v + ' = ' + val, false);
  }).catch(function (e) { toast(e.message, true); });
}
function loadEsp32(){
  var info = $('espCamInfo');
  api('/api/esp32/cam_status').then(function (d) {
    var j = d.esp32 || {};
    if (j.framesize != null && $('espSize').querySelector('option[value="' + j.framesize + '"]'))
      $('espSize').value = j.framesize;
    if (j.quality != null && $('espQuality').querySelector('option[value="' + j.quality + '"]'))
      $('espQuality').value = j.quality;
    ['brightness', 'contrast', 'saturation'].forEach(function (k) {
      var id = 'esp' + k.charAt(0).toUpperCase() + k.slice(1);
      if (j[k] != null && $(id)) { $(id).value = j[k]; $(id + 'V').textContent = j[k]; }
    });
    espFlip.vflip = j.vflip ? 1 : 0;
    espFlip.hmirror = j.hmirror ? 1 : 0;
    info.textContent = 'ESP32 ' + d.base +
      ' — ' + (j.cam_on === 0 ? 'cam ĐANG TẮT (bấm "Bật cam ESP32" để xem stream)' : 'cam đang bật') +
      (d.push_alive ? ' · push ' + d.push_count + ' khung' : '');
  }).catch(function (e) {
    info.textContent = 'Chưa điều khiển được ESP32: ' + e.message +
      ' (kiểm tra STREAM_URL hoặc IP PUSH)';
  });
}
$('espSize').addEventListener('change', function (e) { espCtl('framesize', e.target.value); });
$('espQuality').addEventListener('change', function (e) { espCtl('quality', e.target.value); });
[['espBrightness', 'brightness'], ['espContrast', 'contrast'], ['espSaturation', 'saturation']].forEach(function (p) {
