    rd.readAsDataURL(f);
  });
  e.target.value = '';
});
$('btnGrab').addEventListener('click', function () {
  grabFrame().then(function (img) { tImages.push(img); renderTPrev(); })
    .catch(function (e) { toast(e.message, true); });
});

function runTest(capture) {
  if (!tImages.length) { toast('Chọn ảnh hoặc bấm "Dùng khung preview"', true); return; }
  var url = '/api/recognize' + (capture ? '?capture=1' : '');
