var CFG_FIELDS = [
  ['cfFps', 'process_fps'], ['cfJpeg', 'jpeg_quality'],
  ['cfScore', 'detect_score'], ['cfMin', 'min_face_size'],
  ['cfThresh', 'match_threshold'], ['cfMargin', 'match_margin'],
  ['cfConfirm', 'track_confirm'], ['cfAge', 'track_max_age'],
  ['cfSmooth', 'track_smooth']
];
function fillConfig(c) {
  CFG_FIELDS.forEach(function (p) { if (c[p[1]] != null) $(p[0]).value = c[p[1]]; });
  if (c.track_backend) $('cfBackend').value = c.track_backend;
  if (c.track_enabled != null) $('cfTrack').checked = !!c.track_enabled;
  if (c.stream_url && !$('streamUrl').value) $('streamUrl').value = c.stream_url;
  var en = c.engine || {};
  $('cfgInfo').textContent = (en.detector || '?') + ' + ' + (en.recognizer || '?') +
    ' · ngưỡng ' + (en.threshold != null ? en.threshold : '?') + ' (' + (en.metric || '?') + ')' +
    ' · ' + (en.identities || 0) + ' người / ' + (en.faces_loaded || 0) + ' mẫu';
}
$('btnSaveCfg').addEventListener('click', function () {
  var payload = {track_enabled: $('cfTrack').checked, track_backend: $('cfBackend').value};
  CFG_FIELDS.forEach(function (p) { payload[p[1]] = $(p[0]).value; });
  $('cfgMsg').textContent = 'Đang lưu...';
  api('/api/config', {
    method: 'POST', headers: {'Content-Type': 'application/json'},
    body: JSON.stringify(payload)
  }).then(function (d) {
    $('cfgMsg').textContent = '';
    fillConfig(d);
    toast('Đã lưu cấu hình' + (d.updated && d.updated.length ? ': ' + d.updated.join(', ') : ''), false);
  }).catch(function (e) { $('cfgMsg').textContent = 'Không lưu được: ' + e.message; });
});
$('btnDefCfg').addEventListener('click', function () {
  api('/api/config').then(function (c) {
    var d = c.defaults || {};
    fillConfig(Object.assign({}, d, c));
    toast('Đã điền giá trị mặc định — bấm Lưu để áp dụng', false);
  }).catch(function (e) { toast(e.message, true); });
});

/* ---------------- trạng thái định kỳ ---------------- */
var ENGINE_NAME = {yunet: 'YuNet', haar: 'Haar', sface: 'SFace', lbph: 'LBPH'};
var lastEngine = null;
var hadDets = false;
function distLabel() {
  return (lastEngine && lastEngine.metric === 'cosine') ? 'khoảng cách' : 'điểm';
}

function pollStatus(){
  api('/api/status').then(function (d) {
    var cam = d.camera;
    var en = d.engine || {};
    lastEngine = en;
    $('camDot').className = 'dot' + (cam.connected ? ' on' : '');
    $('camState').textContent = cam.connected
      ? 'đang chạy (' + (cam.fps || '?') + ' fps' + (cam.resolution ? ', ' + cam.resolution : '') + ')'
      : (cam.url ? 'mất kết nối' : 'chưa bật');
    $('camErr').textContent = cam.error ? ('Lưu ý: ' + cam.error) : '';
    if (cam.url && !$('streamUrl').value) $('streamUrl').value = cam.url;
    var src = {phone: 'Điện thoại', esp32: 'ESP32', test: 'Test'}[d.frame_source] || 'không có';
    $('srcState').textContent = src;
    var esp = d.esp32 || {};
    var hint = $('esp32Hint');
    if (hint) {
      if (esp.push_alive) {
        hint.textContent = 'ESP32 đang PUSH (' + esp.push_count + ' khung) — nguồn ưu tiên.';
      } else if (d.frame_source === 'esp32') {
        hint.textContent = 'ESP32 đang PULL qua ' + (cam.url || 'STREAM_URL') + '.';
      } else {
        hint.textContent = '';
      }
    }
    $('modelState').textContent =
      (ENGINE_NAME[en.detector] || en.detector || '?') + ' + ' +
      (ENGINE_NAME[en.recognizer] || en.recognizer || '?') +
      (d.students ? ' · ' + d.students + ' người' : '');
    $('stuCount').textContent = d.students;
    $('faceCount').textContent = d.faces == null ? 0 : d.faces;
    $('matchCount').textContent = d.matched == null ? 0 : d.matched;
    var t = en.timing_ms || {};
    $('speedState').textContent = t.total_ms
      ? Math.round(t.total_ms) + ' ms/khung' +
        (en.tracking ? ' · ' + en.tracks + ' vùng theo dõi' : '')
      : '—';
    var live = $('liveBadge');
    var off = (d.frame_source === 'none');
    live.textContent = off ? 'chờ tín hiệu' : ('đang xử lý (' + d.frame_age + 's)');
    live.classList.toggle('off', off);
    live.parentNode.classList.toggle('no-signal', off);

    var box = $('dets');
    var html;
    if (!d.results.length) {
      html = '<span class="muted">' +
        (d.frame_source !== 'none' ? 'Không thấy khuôn mặt trong khung.' :
         'Chưa có khung hình nào được xử lý.') + '</span>';
    } else {
      html = d.results.map(function (r) {
        var tag = r.track_id != null ? '<span class="tag">#' + r.track_id + '</span>' : '';
        var dist = '<small>(' + distLabel() + ' ' + esc(r.confidence) + ')</small>';
        if (r.match)
          return '<span class="det">' + tag + '<b>' + esc(r.full_name) + '</b> · ' +
            esc(r.class_name) + ' · ' + esc(r.date_of_birth) + ' ' + dist + '</span>';
        if (r.confirming)
          return '<span class="det wait">' + tag + 'Đang xác nhận…' +
            ' <small>(' + esc(r.full_name || '—') + ') ' + dist + '</small></span>';
        return '<span class="det warn">' + tag + 'Chưa nhận diện ' + dist + '</span>';
      }).join('');
    }
    setHTML(box, html);

    var has = !!d.results.length;
    if (has && !hadDets) {
      box.classList.remove('in');
      void box.offsetWidth;
      box.classList.add('in');
      clearTimeout(box._in);
      box._in = setTimeout(function () { box.classList.remove('in'); }, 500);
    }
    hadDets = has;
  }).catch(function () {});
}

function pollLog(){
  api('/api/log?limit=25').then(function (d) {
    if (!d.log.length) return;
    $('logDistHead').textContent =
      (lastEngine && lastEngine.metric === 'cosine') ? 'Khoảng cách' : 'Điểm';
    setHTML($('logBody'), d.log.map(function (l) {
      return '<tr><td>' + esc(l.seen_at) + '</td><td>' + esc(l.full_name) + '</td>' +
        '<td>' + esc(l.class_name || '') + '</td>' +
        '<td class="num">' + esc(l.confidence == null ? '' : l.confidence) + '</td></tr>';
    }).join(''));
  }).catch(function () {});
}

/* ---------------- khởi động ---------------- */
(function init(){
  api('/api/config').then(fillConfig).catch(function () {});
  pollStatus(); pollLog(); loadEsp32();
  setInterval(pollStatus, 1500);
  setInterval(pollLog, 5000);
  setInterval(loadEsp32, 15000);
})();
</script>
{% endblock %}

